//! Conformance check of `xtp_shader::gfx10` (instruction names and lengths)
//! against the public LLVM MC AMDGPU GFX10 encoding corpus (`llvmorg-19.1.7`,
//! Apache-2.0 WITH LLVM-exception), generated by `cargo xtask gfx10-corpus`
//! into `crates/xtp-shader/tests/data/gfx10-llvm-mc-*.txt`.
//!
//! Every encoding in the corpus must:
//! 1. Decode without error via `gfx10::decode_one`.
//! 2. Decode to the exact same dword length as LLVM MC (100% length agreement).
//! 3. Match LLVM MC's mnemonic (after accounting for encoding-form suffixes
//!    such as `_e32`, `_e64`, `_dpp`, `_sdwa`), or match a pinned decoder gap
//!    or intentional GFX10.1 legacy opcode name.

use std::collections::{BTreeMap, BTreeSet};
use std::path::Path;

use xtp_shader::gfx10::{self, Encoding};

/// LLVM 19.1.7 gates MAD/MAC on `HasMadMacF32Insts` and legacy FMA/FMAC on
/// `HasFmaLegacy32` (GFX10.3, in the `GFX10_B` decoder namespace).
/// `gfx1013` combines the GFX10.1 MAD/MAC feature with `GFX10_AEncoding` for BVH.
/// The title's programs use `v_mad_f32` and `v_mac_f32` alongside BVH instructions,
/// so XTP keeps the GFX10.1 legacy names at VOP3 0x140 and VOP2 0x006.
const GFX10_1_LEGACY_NAMES: &[(&str, &str)] = &[
    ("v_fma_legacy_f32", "v_mad_legacy_f32"),
    ("v_fmac_legacy_f32", "v_mac_legacy_f32"),
];

/// Valid LLVM MC mnemonics for which XTP currently returns no name.
const KNOWN_DECODER_GAPS: &[&str] = &[];

fn load_corpus() -> Vec<(String, Vec<u32>)> {
    let dir = Path::new(env!("CARGO_MANIFEST_DIR")).join("tests/data");
    let mut shards: Vec<_> = std::fs::read_dir(&dir)
        .unwrap_or_else(|e| panic!("reading {}: {e}", dir.display()))
        .map(|e| e.expect("reading corpus directory entry").path())
        .filter(|p| {
            p.file_name()
                .and_then(|n| n.to_str())
                .is_some_and(|n| n.starts_with("gfx10-llvm-mc-") && n.ends_with(".txt"))
        })
        .collect();
    shards.sort();
    assert!(
        !shards.is_empty(),
        "no gfx10-llvm-mc-*.txt corpus shards in {}",
        dir.display()
    );

    let mut out = Vec::new();
    let mut expected_count = None;
    for shard in shards {
        let text = std::fs::read_to_string(&shard)
            .unwrap_or_else(|e| panic!("reading {}: {e}", shard.display()));
        let count = text
            .lines()
            .find_map(|line| line.strip_prefix("# Corpus entries: "))
            .and_then(|count| count.parse::<usize>().ok())
            .filter(|&count| count > 0)
            .unwrap_or_else(|| panic!("{}: missing or invalid corpus count", shard.display()));
        assert_eq!(
            *expected_count.get_or_insert(count),
            count,
            "{}: inconsistent corpus count",
            shard.display()
        );
        for (line_no, raw) in text.lines().enumerate() {
            let line = raw.trim();
            if line.is_empty() || line.starts_with('#') {
                continue;
            }
            let mut parts = line.split_whitespace();
            let mnem = parts
                .next()
                .unwrap_or_else(|| panic!("{}:{}: missing mnemonic", shard.display(), line_no + 1));
            let words: Vec<u32> = parts
                .map(|w| {
                    u32::from_str_radix(w, 16).unwrap_or_else(|e| {
                        panic!("{}:{}: bad hex {w:?}: {e}", shard.display(), line_no + 1)
                    })
                })
                .collect();
            assert!(
                !words.is_empty(),
                "{}:{}: no words",
                shard.display(),
                line_no + 1
            );
            out.push((mnem.to_string(), words));
        }
    }
    assert_eq!(Some(out.len()), expected_count, "corpus entry count");
    out
}

/// Strip LLVM MC encoding-form suffixes (`_e32`, `_e64`, `_dpp`, `_sdwa`) so
/// the mnemonic can be compared against `gfx10::Instruction::name()`.
fn strip_llvm_suffix(m: &str) -> &str {
    for suffix in ["_e64_dpp", "_e32", "_e64", "_dpp", "_sdwa"] {
        if let Some(base) = m.strip_suffix(suffix) {
            return base;
        }
    }
    m
}

#[test]
fn decodes_gfx10_1_legacy_mad_mac() {
    // GFX10.1 encodings from the checked-in LLVM MC corpus.
    let cases: &[(&[u32], Encoding, u16, &str)] = &[
        (
            &[0xd540_0005, 0x000e_0501],
            Encoding::Vop3,
            0x140,
            "v_mad_legacy_f32",
        ),
        (&[0x0c0a_0401], Encoding::Vop2, 0x006, "v_mac_legacy_f32"),
        (
            &[0xd506_0005, 0x0000_0501],
            Encoding::Vop3,
            0x106,
            "v_mac_legacy_f32",
        ),
    ];
    for &(words, encoding, opcode, name) in cases {
        let bytes: Vec<_> = words.iter().flat_map(|w| w.to_le_bytes()).collect();
        let inst = gfx10::decode_one(&bytes).unwrap();
        assert_eq!(inst.words, words);
        assert_eq!((inst.encoding, inst.opcode), (encoding, opcode));
        assert_eq!(inst.name(), Some(name));
    }
}

#[test]
fn gfx10_decoder_matches_llvm_mc_corpus() {
    let corpus = load_corpus();
    let known: BTreeMap<&str, Option<&str>> = GFX10_1_LEGACY_NAMES
        .iter()
        .map(|&(llvm, xtp)| (llvm, Some(xtp)))
        .chain(KNOWN_DECODER_GAPS.iter().map(|&llvm| (llvm, None)))
        .collect();
    let mut seen_known: BTreeSet<&str> = BTreeSet::new();
    let mut seen_encodings: BTreeSet<String> = BTreeSet::new();
    let mut unexpected_errors = Vec::new();
    let mut unexpected_lengths = Vec::new();
    let mut unexpected_names = Vec::new();

    for (mnem, words) in &corpus {
        let mut bytes = Vec::with_capacity(words.len() * 4);
        for &w in words {
            bytes.extend_from_slice(&w.to_le_bytes());
        }
        let fmt_words = || {
            words
                .iter()
                .map(|w| format!("{w:08x}"))
                .collect::<Vec<_>>()
                .join(" ")
        };

        let inst = match gfx10::decode_one(&bytes) {
            Ok(i) => i,
            Err(e) => {
                unexpected_errors.push(format!("{mnem} [{}] -> {e}", fmt_words()));
                continue;
            }
        };
        seen_encodings.insert(format!("{:?}", inst.encoding));

        if inst.words.len() != words.len() {
            unexpected_lengths.push(format!(
                "{mnem} [{}] -> decoded {} dwords, expected {}",
                fmt_words(),
                inst.words.len(),
                words.len()
            ));
            continue;
        }

        let got_name = inst.name();
        let expected_base = strip_llvm_suffix(mnem);
        if got_name == Some(expected_base) || got_name == Some(mnem.as_str()) {
            continue;
        }
        if let Some(&expected_xtp) = known.get(expected_base)
            && got_name == expected_xtp
        {
            seen_known.insert(expected_base);
            continue;
        }
        unexpected_names.push(format!(
            "{mnem} [{}] -> xtp={got_name:?}, expected={expected_base:?}",
            fmt_words()
        ));
    }

    assert!(
        unexpected_errors.is_empty(),
        "unexpected decode errors ({}):\n{}",
        unexpected_errors.len(),
        unexpected_errors
            .iter()
            .take(20)
            .cloned()
            .collect::<Vec<_>>()
            .join("\n")
    );
    assert!(
        unexpected_lengths.is_empty(),
        "unexpected length mismatches ({}):\n{}",
        unexpected_lengths.len(),
        unexpected_lengths
            .iter()
            .take(20)
            .cloned()
            .collect::<Vec<_>>()
            .join("\n")
    );
    assert!(
        unexpected_names.is_empty(),
        "unexpected name mismatches ({}):\n{}",
        unexpected_names.len(),
        unexpected_names
            .iter()
            .take(20)
            .cloned()
            .collect::<Vec<_>>()
            .join("\n")
    );

    // Remove a pin when its mnemonic agrees with LLVM MC.
    let stale: Vec<&str> = known
        .keys()
        .copied()
        .filter(|k| !seen_known.contains(k))
        .collect();
    assert!(
        stale.is_empty(),
        "pinned name differences no longer observed: {stale:?}"
    );

    // Sanity check that the corpus exercises almost every GFX10 encoding
    // family (all except 32-bit VINTRP if LLVM tests only use VOP3 VINTRP).
    for enc in [
        Encoding::Sop2,
        Encoding::Sopk,
        Encoding::Sop1,
        Encoding::Sopc,
        Encoding::Sopp,
        Encoding::Smem,
        Encoding::Vop2,
        Encoding::Vop1,
        Encoding::Vopc,
        Encoding::Vop3,
        Encoding::Vop3p,
        Encoding::Ds,
        Encoding::Mubuf,
        Encoding::Mtbuf,
        Encoding::Mimg,
        Encoding::Exp,
        Encoding::Flat,
        Encoding::Global,
        Encoding::Scratch,
    ] {
        assert!(
            seen_encodings.contains(&format!("{enc:?}")),
            "corpus did not exercise encoding {enc:?}"
        );
    }
}
